-- Mehran Public Higher Secondary School ERP schema
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role text not null check(role in ('admin','principal','teacher','student','parent','exam')), photo_url text, created_at timestamptz default now());
create table if not exists classes(id bigint generated by default as identity primary key, name text not null, section text not null, academic_year text not null, unique(name,section,academic_year));
create table if not exists students(id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete set null, name text not null, roll text unique not null, father text, class_id bigint references classes(id), photo_url text, status text default 'Active', created_at timestamptz default now());
create table if not exists subjects(id bigint generated by default as identity primary key, name text unique not null);
create table if not exists teachers(id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete set null, name text not null, phone text, photo_url text, salary numeric default 0, status text default 'Active', created_at timestamptz default now());
create table if not exists teacher_assignments(id bigint generated by default as identity primary key, teacher_id bigint references teachers(id) on delete cascade, subject_id bigint references subjects(id) on delete cascade, class_id bigint references classes(id) on delete cascade, academic_year text not null, active boolean default true, unique(teacher_id,subject_id,class_id,academic_year));
create table if not exists attendance(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, teacher_id bigint references teachers(id), subject_id bigint references subjects(id), class_id bigint references classes(id), date date not null, status text not null check(status in ('Present','Absent','Leave','Late')), unique(student_id,subject_id,date));
create table if not exists results(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, teacher_id bigint references teachers(id), subject_id bigint references subjects(id), exam_name text not null, marks numeric not null check(marks>=0), total numeric not null check(total>0), created_at timestamptz default now());
create table if not exists fees(id bigint generated by default as identity primary key, student_id bigint references students(id) on delete cascade, month date not null, amount numeric not null, paid numeric default 0, unique(student_id,month));
create table if not exists staff(id bigint generated by default as identity primary key, name text not null, category text not null, phone text, salary numeric default 0, photo_url text, status text default 'Active');
create table if not exists staff_dues(id bigint generated by default as identity primary key, staff_id bigint references staff(id) on delete cascade, month date not null, due numeric not null, paid numeric default 0, unique(staff_id,month));
create table if not exists exam_timetables(id bigint generated by default as identity primary key, exam_name text not null, class_id bigint references classes(id), subject_id bigint references subjects(id), exam_date date not null, start_time time not null, end_time time not null, room text, instructions text, status text default 'Draft');
create table if not exists admissions(id bigint generated by default as identity primary key, applicant_name text not null, class_name text, phone text, photo_url text, status text default 'Pending', created_at timestamptz default now());
create table if not exists job_vacancies(id bigint generated by default as identity primary key, title text not null, category text not null, description text, deadline date, status text default 'Open');
create table if not exists job_applications(id bigint generated by default as identity primary key, vacancy_id bigint references job_vacancies(id) on delete cascade, name text not null, phone text, cv_url text, status text default 'Pending', created_at timestamptz default now());
create table if not exists homework(id bigint generated by default as identity primary key, teacher_id bigint references teachers(id), class_id bigint references classes(id), subject_id bigint references subjects(id), title text not null, description text, due_date date);
create table if not exists expenses(id bigint generated by default as identity primary key, title text not null, category text, amount numeric not null, expense_date date default current_date);
create table if not exists leave_requests(id bigint generated by default as identity primary key, profile_id uuid references profiles(id), from_date date not null, to_date date not null, reason text, status text default 'Pending');
create table if not exists inventory(id bigint generated by default as identity primary key, item text not null, quantity integer default 0, condition text);
create table if not exists transport(id bigint generated by default as identity primary key, vehicle text, driver text, route text, student_count integer default 0);
create table if not exists library_books(id bigint generated by default as identity primary key, title text not null, author text, copies integer default 1, issued integer default 0);
create table if not exists notices(id bigint generated by default as identity primary key, title text not null, body text not null, date date default current_date);
create table if not exists audit_logs(id bigint generated by default as identity primary key, user_id uuid references auth.users(id), action text not null, table_name text, record_id bigint, created_at timestamptz default now());

-- Enable RLS. Production policies should be completed before real data is used.
DO $$ DECLARE t text; BEGIN FOR t IN SELECT unnest(ARRAY['profiles','classes','students','subjects','teachers','teacher_assignments','attendance','results','fees','staff','staff_dues','exam_timetables','admissions','job_vacancies','job_applications','homework','expenses','leave_requests','inventory','transport','library_books','notices','audit_logs']) LOOP EXECUTE format('alter table %I enable row level security',t); END LOOP; END $$;
-- Helper function for role checks.
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid() $$;
-- Example baseline policies: authenticated users can read only after role-aware policies are reviewed.
create policy "authenticated read students" on students for select to authenticated using (true);
create policy "admin manage students" on students for all to authenticated using (public.current_role() in ('admin','principal')) with check (public.current_role() in ('admin','principal'));
create policy "authenticated read teachers" on teachers for select to authenticated using (true);
create policy "admin manage teachers" on teachers for all to authenticated using (public.current_role() in ('admin','principal')) with check (public.current_role() in ('admin','principal'));
create policy "teacher attendance insert" on attendance for insert to authenticated with check (public.current_role() in ('admin','teacher'));
create policy "authenticated read attendance" on attendance for select to authenticated using (true);
create policy "teacher results insert" on results for insert to authenticated with check (public.current_role() in ('admin','teacher','exam'));
create policy "authenticated read results" on results for select to authenticated using (true);
create policy "admin fees" on fees for all to authenticated using (public.current_role() in ('admin','principal')) with check (public.current_role() in ('admin','principal'));
create policy "student own fees" on fees for select to authenticated using (student_id in (select id from students where user_id=auth.uid()));
create policy "exam department manages exam timetable" on exam_timetables for all to authenticated using (public.current_role() in ('admin','principal','exam')) with check (public.current_role() in ('admin','principal','exam'));
